    <component name="pp_simple_novisco_type">
        <variable name="t" public_interface="in" units="second"/>
        <!-- Constitutive parameters-->
        <variable name="I" public_interface="in" units="Js2_per_m6"/>
        <variable name="C" public_interface="in" units="m6_per_J"/>
        <variable name="R" public_interface="in" units="Js_per_m6"/>
        <variable name="Rp" public_interface="in" units="Js_per_m6"/>
        <variable name="fracR" public_interface="in" units="dimensionless"/>
        <variable name="Rp_loc" public_interface="out" units="Js_per_m6"/>
        <variable name="Rd_loc" public_interface="out" units="Js_per_m6"/>
        <variable name="R_v" public_interface="out" units="Js_per_m6"/>
        <math xmlns="http://www.w3.org/1998/Math/MathML">
            <apply>
                <eq/>
                <ci>Rp_loc</ci>
                <piecewise>
                    <piece>
                        <ci>Rp</ci>
                        <apply>
                            <gt/>
                            <ci>Rp</ci>
                            <cn cellml:units="Js_per_m6">0.0</cn>
                        </apply>
                    </piece>
                    <piece>
                        <apply>
                            <times/>
                            <ci>R</ci>
                            <ci>fracR</ci>
                        </apply>
                        <apply>
                            <and/>
                            <apply>
                                <leq/>
                                <ci>Rp</ci>
                                <cn cellml:units="Js_per_m6">0.0</cn>
                            </apply>
                            <apply>
                                <geq/>
                                <ci>fracR</ci>
                                <cn cellml:units="dimensionless">0.0</cn>
                            </apply>
                        </apply>
                    </piece>
                    <piece>
                        <apply>
                            <times/>
                            <ci>R</ci>
                            <cn cellml:units="dimensionless">0.5</cn>
                        </apply>
                        <apply>
                            <and/>
                            <apply>
                                <leq/>
                                <ci>Rp</ci>
                                <cn cellml:units="Js_per_m6">0.0</cn>
                            </apply>
                            <apply>
                                <lt/>
                                <ci>fracR</ci>
                                <cn cellml:units="dimensionless">0.0</cn>
                            </apply>
                        </apply>
                    </piece>
                </piecewise>
            </apply>
            <apply>
                <eq/>
                <ci>Rd_loc</ci>
                <apply>
                    <minus/>
                    <ci>R</ci>
                    <ci>Rp_loc</ci>
                </apply>
            </apply>
            <apply>
                <eq/>
                <ci>R_v</ci>
                <apply>
                    <divide/>
                    <cn cellml:units="second">0.01</cn>
                    <ci>C</ci>
                </apply>
            </apply>
        </math>
        <!-- State Variables-->
        <variable name="q_0" public_interface="in" units="m3"/>
        <variable name="u_0" public_interface="in" units="J_per_m3"/>
        <variable name="u_ext" public_interface="in" units="J_per_m3"/>
        <variable name="u_in" public_interface="in" units="J_per_m3"/>
        <variable initial_value="0.0" name="v" public_interface="out" units="m3_per_s"/>
        <variable name="u" public_interface="out" units="J_per_m3"/>
        <variable name="u_C" public_interface="out" units="J_per_m3"/>
        <variable initial_value="0.0" name="v_d" public_interface="out" units="m3_per_s"/>
        <variable name="u_out" public_interface="in" units="J_per_m3"/>
        <variable initial_value="0.0" name="q_C" public_interface="out" units="m3"/>
        <variable name="q" public_interface="out" units="m3"/>
        <math xmlns="http://www.w3.org/1998/Math/MathML">
            <apply>
                <eq/>
                <ci>q</ci>
                <apply>
                    <plus/>
                    <ci>q_C</ci>
                    <ci>q_0</ci>
                </apply>
            </apply>
            <!-- Conservation Laws-->
            <apply>
                <eq/>
                <apply>
                    <diff/>
                    <bvar>
                        <ci>t</ci>
                    </bvar>
                    <ci>v</ci>
                </apply>
                <apply>
                    <divide/>
                    <apply>
                        <minus/>
                        <apply>
                            <minus/>
                            <ci>u_in</ci>
                            <ci>u</ci>
                        </apply>
                        <apply>
                            <times/>
                            <ci>Rp_loc</ci>
                            <ci>v</ci>
                        </apply>
                    </apply>
                    <apply>
                        <divide/>
                        <ci>I</ci>
                        <cn cellml:units="dimensionless">2</cn>
                    </apply>
                </apply>
            </apply>
            <apply>
                <eq/>
                <apply>
                    <diff/>
                    <bvar>
                        <ci>t</ci>
                    </bvar>
                    <ci>q_C</ci>
                </apply>
                <apply>
                    <minus/>
                    <ci>v</ci>
                    <ci>v_d</ci>
                </apply>
            </apply>
            <apply>
                <eq/>
                <ci>u_C</ci>
                <apply>
                    <divide/>
                    <ci>q_C</ci>
                    <ci>C</ci>
                </apply>
            </apply>
            <apply>
                <eq/>
                <ci>u</ci>
                <apply>
                    <plus/>
                    <ci>u_0</ci>
                    <ci>u_C</ci>
                    <ci>u_ext</ci>
                </apply>
            </apply>
            <!--+R_v*(v-v_d);-->
            <apply>
                <eq/>
                <apply>
                    <diff/>
                    <bvar>
                        <ci>t</ci>
                    </bvar>
                    <ci>v_d</ci>
                </apply>
                <apply>
                    <divide/>
                    <apply>
                        <minus/>
                        <apply>
                            <minus/>
                            <ci>u</ci>
                            <ci>u_out</ci>
                        </apply>
                        <apply>
                            <times/>
                            <ci>Rd_loc</ci>
                            <ci>v_d</ci>
                        </apply>
                    </apply>
                    <apply>
                        <divide/>
                        <ci>I</ci>
                        <cn cellml:units="dimensionless">2</cn>
                    </apply>
                </apply>
            </apply>
        </math>
    </component>
